bool IsOOFileExtension(wchar_t const * Extension)
{
    for (size_t i = 0; i < OOFileExtensionTableSize; i++)
    {
        if (0 == _wcsicmp(Extension, OOFileExtensionTable[i].ExtensionU))
            return true;
    }

    return false;
}
